def lru_cache(maxsize=128, typed=False):
        """Decorator to wrap a function with a memoizing callable that saves
        up to `maxsize` results based on a Least Recently Used (LRU)
        algorithm.

        Parameters:
            maxsize (int): The maximum number of Memoized results to keep.
            typed (bool): If True, use type-specific memoization. Otherwise, use general memoization.

        Returns:
            A decorator which memoizes the results of the decorated function.
        """

        def memoize(function):
            memo = {}

            @functools.wraps(function)
            def wrapper(*args, **kwargs):
                # If we're using type-specific memoization, create a separate cache for each type
                # that's encountered.
                if typed:
                    if not isinstance(args[0], tuple):
                        args = (args[0],)

                    key = (args[0],) + args[1:]
                    if key not in memo:
                        memo[key] = function(*args, **kwargs)
                # Otherwise, use a general memoization cache.
                else:
                    if not isinstance(args, tuple):
                        args = (args,)

                    key = args + tuple(kwargs.items())
                    if key not in memo:
                        memo[key] = function(*args, **kwargs)

                return memo[key]

            return wrapper

        return memoize

