    cache = {}

    @functools.wraps(f)
    def memoized_f(*args, **kwargs):
        key = (args, frozenset(kwargs.items()))
        if key not in cache or cache[key] is None:
            cache[key] = f(*args, **kwargs)
        return cache[key]

    return memoized_f

