def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    cache = dict()

    def decorator(func):
        nonlocal cache

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            try:
                cache[key][1] += 1
            except KeyError:
                result = func(*args, **kwargs)
                cache[key] = (result, 1)
                if len(cache) > maxsize:
                    cache = dict(sorted(cache.items(),
                                        key=lambda x: x[1][1],
                                        reverse=True))
            return cache[key][0]

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
        """
        def check_args(func, args, kwargs):
            return (args, kwargs)

        def get_cache_key(args, kwargs):
            if typed:
                key = (type(args[0]), args[0], args[1])
            else:
                key = args + (kwargs,)
            return key

        def wrapper(func):
            cache = {}
            use_counts = {}

            @functools.wraps(func)
            def memoized(*args, **kwargs):
                key = get_cache_key(args, kwargs)
                if key in cache:
                    use_counts[key] += 1
                    return cache[key]

                result = check_args(func, args, kwargs)

                if result is not None:
                    cache[key] = result
                    if len(cache) > maxsize:
                        # remove the least used entry
                        key = min(use_counts, key=use_counts.get)
                        del cache[key], use_counts[key]
                    else:
                        use_counts[key] = 1

                return memoized

            return memoized

        return wrapper

