    callable that saves results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    key = key(*args, **kwargs)
                    if key not in cache:
                        cache[key] = func(*args, **kwargs)
