def cachedmethod(cache, *, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    Arguments:
        cache: The cache where results should be saved
        key (str or function): key of the cache
        lock (Any): Lock for the cache

    """
    def wrapper(func):
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            result = cache.get(key(*args, **kwargs))
            if result is not None:
                return result
            result = func(*args, **kwargs)
            if not cache.add(key(*args, **kwargs), result, lock=lock):
                cache.set(key(*args, **kwargs), result, lock=lock)
            return result
        return wrapped
    return wrapper

