    return decorator

class Element(object):
    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        if not isinstance(e, Exception):
            raise TypeError("'e' must be an instance of Exception")

        if not isinstance(max_level, int) or max_level < 0:
            raise ValueError("'max_level' must be a positive integer")

        if not isinstance(max_path_level, int) or max_path_level < 0:
            raise ValueError("'max_path_level' must be a positive integer")

        rv = [str(e)]

        level = 0
        while True:
            exception, _, tb = sys.exc_info()
            if exception is None or level >= max_level:
                break
            rv += [
                "\n" + "  " * level + "File " + tb.tb_frame.f_code.co_filename + ", line " + str(tb.tb_lineno),
                "\n" + "  " * level + repr(tb.tb_frame.f_locals.get("self", "")),
            ]
            level += 1
            tb = tb.tb_next

        return "".join(rv)

def extostr(cls, e, max_level=30, max_path_level=5):
    msg = cls._etype(e) + ': ' + cls._emsg(e)
    if max_path_level > 0:
        stack = cls._stack(e, max_level)
        if stack:
            msg += '\n' + cls._stk(stack[1:], max_path_level)
    return msg

def _etype(cls, e):
    return e.__class__.__name__

