    return e._MSGERROR(e, limit=250)

def _stack(cls, e, max_level):
    return [cls._stk_str(l[0], l[1], max_level) for l in e._STACK] if e._STACK else []

def _stk_str(cls, file, fun, max_level):
    if fun.split('.')[-1].startswith('_'):
        fun = 'private method'
    elif fun.split('.')[-1] == '__init__':
        fun = '__init__'
    elif fun == '<lambda>':
        fun = 'lambda'
    else:
        fun = fun.split('.')[-1]

    return '{}.{}{}'.format(file.split('/')[-1], fun, '/' if max_level > 1 else '')

def file_to_textbuffer(file_name, encoding):
    """
    Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    try:
        with open(file_name, "rb") as f:
            buf = f.read()
        if encoding:
            return buf.decode(encoding)
        else:
            return buf
    except:
        return None

