    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if isinstance(sequence, Declaration):
        yield sequence
    elif isinstance(sequence, tuple):
        for elem in sequence:
            if not isinstance(elem, (Declaration, AbstractInterface)):
                for sub in _normalizeargs(elem):
                    yield sub
            elif isinstance(elem, AbstractInterface):
                yield elem
            else:
                raise ValueError("Expected a Declaration or an AbstractInterface, got " + str(type(elem)))
    else:
        raise ValueError("Expected a Declaration, a tuple, or a single interface, got " + str(type(sequence)))

    if output is not None:
        for elem in sequence:
            if isinstance(elem, (Declaration, AbstractInterface)):
                yield elem
            elif isinstance(elem, tuple):
                for sub in _normalizeargs(elem):
                    yield sub
            else:
