    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single 
    interfaces.

    Anything but individial interfaces or implements specs will be expanded. 
    """
    if not isinstance(sequence, tuple):
        sequence = (sequence,)

    normalized = []
    for element in sequence:
        if (isinstance(element, Declaration) or isinstance(element, Interface) or
                isinstance(element, Implements)):
            normalized.append(element.copy())
        elif isinstance(element, Interface):
            normalized.append(element)
        elif isinstance(element, str):
            normalized.append(Interface(name=element))
        elif isinstance(element, tuple):
            normalized.extend(_normalizeargs(element))
        else:
            raise Exception(f"Unexpected element of type {type(element)}: {element}")

    if output:
        output.extend(normalized)
    else:
        return normalized

