def to_csv(self, separator: Optional[str] = ","):
    """Convert graph's points to CSV.

    :param separator: Delimiter for value separation, defaults to ','
    """
    # Check if graph is not multidimensional, if so raise ValueError
    if len(self.points[0]) > 1:
        raise ValueError("Graph must be unidimensional to convert to CSV")

    # Create header if not None
    if header:
        csv_header = f"{header}\n"
    else:
        csv_header = ""

    # Iterate through points and convert each coordinate to string
    csv_lines = [
        f"{point[0]}{separator}{str(point[0])}" for point in self.points
    ]
    csv_lines += [f"{separator}{str(point[1])}" for point in self.points]
    return csv_header + "\n".join(csv_lines)

