def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    res = []
    for a in args:
        if isinstance(a, And):
            if a.left in res:
                res.remove(a.left)
                res.append(a.left | a.right)
            elif a.right in res:
                res.remove(a.right)
                res.append(a.left & a.right)
            else:
                res.append(a)
        elif isinstance(a, Or):
            if a.left == a.right:
                res.append(a.left)
            else:
                res.append(a)
        else:
            res.append(a)

    return res

def absorb(self, args):
    new_args = []
    for arg in args:
        if arg.operator == "|" and arg.left.name == arg.right.name:
            new_args.append(arg.left)
        elif arg.operator == "|" and arg.left.operator == "~" and arg.left.right.name == arg.right.name:
            new_args.append(And(arg.left.right, arg.right))
        elif arg.operator == "&" and arg.left.name == arg.right.name:
            new_args.append(arg.left)
        elif arg.operator == "&" and arg.left.operator == "~" and arg.left.right.name == arg.right.name:
            new_args.append(Or(arg.left.right, arg.right))
        else:
            new_args.append(arg)
    return new_args

def absorb(args):
    if len(args) == 0:
        return []
    elif len(args) == 1:
        return [args[0]]

    out = []
    for i, arg in enumerate(args):
        for j, other_arg in enumerate(args[i+1:]):
            if arg & other_arg != 0:
                out.extend(absorb(args[:i]+args[i+1:]))
                break

    else:
        out.append(args[0])

    return out

def absorb(self, args):
    result = []
    for arg in args:
        if isinstance(arg, LogicalAnd):
            left = arg.operand1.absorb(args)
            right = arg.operand2.absorb(args)
            if (left == arg.operand1 and right == arg.operand2) or (left == arg.operand2 and right == arg.operand1):
                result.append(left)
            else:
                result.append(LogicalAnd(left, right))
        elif isinstance(arg, LogicalOr):
            left = arg.operand1.absorb(args)
            right = arg.operand2.absorb(args)
            if (left == arg.operand1 and right == arg.operand2) or (left == arg.operand2 and right == arg.operand1):
                result.append(left)
            else:
                result.append(LogicalOr(left, right))
        elif isinstance(arg, LogicalNot):
            right = arg.operand.absorb(args)
            if right == arg.operand:
                result.append(arg)
            else:
                result.append(LogicalNot(right))
        else:
            result.append(arg)
    return result

