        for element in self.objects:
            num_objects += 1
            if validate_objects:
                if isinstance(element, RootObject):
                    if check_digests and element.digest != self.root_digest:
                        if show_warnings:
                            print("Warning: Ignoring object with invalid digest")
                        continue
                    else:
                        good_objects += 1
                else:
                    if show_warnings:
                        print("Warning: Ignoring object of incorrect type")
                    continue

            # Recursively validate the sub-elements of the current element
            for sub_element in element.objects:
                num_objects += 1
                if validate_objects:
                    if isinstance(sub_element, SubObject):
                        if check_digests and sub_element.digest != element.digest:
                            if show_warnings:
                                print("Warning: Ignoring object with invalid digest")
                            continue
                        else:
                            good_objects += 1
                    else:
                        if show_warnings:
                            print("Warning: Ignoring object of incorrect type")
                        continue

                    # Recursively validate the sub-sub-elements of the current sub-element
                    for sub_sub_element in sub_element.objects:
                        num_objects += 1
                        if validate_objects:
                            if isinstance(sub_sub_element, SubSubObject):
                                if check_digests and sub_sub_element.digest != sub_element.digest:
                                    if show_warnings:
                                        print("Warning: Ignoring object with invalid digest")

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Args:
        validate_objects (bool): Whether to validate objects
        check_digests (bool): Whether to check object digests
        show_warnings (bool): Whether to show warnings

    Returns:
        tuple(num_objects, good_objects) - number of objects checked and number of valid objects checked
    """

    # Validate root elements
    num_objects = 0
    good_objects = 0
    if self.root:
        num_objects += 1
        if self.root.has_id:
            good_objects += 1
        if self.root.has_type:
            good_objects += 1

    # Validate child elements
    if validate_objects:
        for child in self.root.child_elements:
            num_objects += 1
            if child.has_id:
                good_objects += 1
            if child.has_type:
                good_objects += 1
            # Check digests
            if check_digests and child.has_digest and child.digest not in self.digests:
                if show_warnings:
                    print(f"Missing digest for element with id '{child.id}' of type '{child.type}'.")
                else:
                    raise KeyError(f"Missing digest for element with id '{child.id}' of type '{child.type}'.")

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return "0.1"

    if version == "0.1":
        return "1.0"

    splitted = version.split(".")
    major = parse_int(splitted[0])
    minor = parse_int(splitted[1])

    if minor == 9:
        return f"{major + 1}.1"
    else:
        return f"{major}.{minor + 1}"

