def find_path_type(path):
    if os.path.isfile(path):  # looks like a file
        # check for the Namaste File Structure
        if re.match(r"^ocfl_(root|object|sidecar).+\.json$", path):
            if re.match("^ocfl_root.+\.json$", path):
                return "root"
            elif re.match("^ocfl_object.+\.json$", path):
                return "object"
            else:
                return "sidecar"
        elif re.match(r"^inventory-.*\.csv$", path):  # looks like an inventory
            return "file"
        else:
            return "other file"
    else:  # looks like a directory
        try:
            files = os.listdir(path)
            if len(files) == 1 and re.match(r"^namaste_.+\.json$", files[0]):
                return "object"
            elif len(files) >= 1 and re.match(r"^inventory-.*\.csv$", files[0]):
                return "file"
            else:
                return "directory"
        except:
            return "other directory"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not os.path.isdir(path):
        return "not a directory"

    if not os.path.isfile(os.path.join(path, "0=*")):
        return "not a Namaste directory"

    with open(os.path.join(path, "0=*"), "rb") as f:
        if f.read(4) == b'OCFL':
            return "root"
        elif f.read(4) == b'ocfl-nd':
            return "object"
        else:
            return "unrecognized file type"

