def deep_merge_nodes(nodes):
    merged_nodes = []
    for node in nodes:
        key, value = node[0], node[1]
        # Handle cases where a key already exists
        if len(merged_nodes) > 0 and key in merged_nodes:
            # Look for the node with the same key in the merged nodes
            for i in range(len(merged_nodes)):
                if key == merged_nodes[i][0]:
                    # If a node with the same key is found, deep merge its values
                    merged_nodes[i][1] = deep_merge(merged_nodes[i][1], value)
                    break
        # If a node with the same key is not found, add the new node to the merged nodes
        else:
            merged_nodes.append((key, value))
