def deep_merge_nodes(nodes):
    def _deep_merge_dict(d1, d2):
        for k, v in d2.items():
            if k in d1 and isinstance(d1[k], dict) and isinstance(v, dict):
                _deep_merge_dict(d1[k], v)
            else:
                d1[k] = v

    def _deep_merge_node(n1, n2):
        if isinstance(n1, ruamel.yaml.nodes.ScalarNode) and isinstance(n2, ruamel.yaml.nodes.ScalarNode):
            return n1
        elif isinstance(n1, ruamel.yaml.nodes.MappingNode) and isinstance(n2, ruamel.yaml.nodes.MappingNode):
            _deep_merge_dict(n1.value, n2.value)
        else:
            raise ValueError("Unable to deep merge nodes of type {type(n1)} and {type(n2)}")

    def _deep_merge_nodes(nodes):
        merged_nodes = []
        for n in nodes:
            key = n[0]
            value = n[1]
            matching_node = next((x[1] for x in merged_nodes if x[0] == key), None)
            if matching_node is None:
                merged_nodes.append((key, _deep_merge_node(value, value)))
            else:
                merged_nodes.remove((key, matching_node))
                merged_nodes.append((key, _deep_merge_node(matching_node, value)))

        return [(k, v) for (k, v) in merged_nodes]

    return _deep_merge_nodes(nodes)

def deep_merge_nodes(nodes):
    # Create a dictionary to store the merged nodes
    merged_nodes = {}

    # Iterate over the input nodes
    for node in nodes:
        # Get the key (which is the first element of the tuple)
        key = node[0]

        # If the key is not already in the merged nodes dictionary, add it
        if key not in merged_nodes:
            merged_nodes[key] = node[1]
        # If the key is already in the merged nodes dictionary, deep merge the values
        else:
            # Extract the existing value for the key
            existing_value = merged_nodes[key]

            # If the existing value is a MappingNode and the new value is also a MappingNode,
            # recursively deep merge the values
            if isinstance(existing_value, MappingNode) and isinstance(node[1], MappingNode):
                merged_nodes[key] = MappingNode(
                    existing_value.tag + node[1].tag,
                    deep_merge_nodes(existing_value.value + node[1].value),
                )
            # If one of the values is not a MappingNode, the new value wins
            else:
                merged_nodes[key] = node[1]

    # Return the final, deeply merged nodes
    return merged_nodes

