def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_namespaces = dict()
    remaining_arguments = []

    for subparser_name, subparser in subparsers.items():
        namespace, unparsed_arguments = parse_known_arguments(subparser, unparsed_arguments)
        if namespace:
            parsed_namespaces[subparser_name] = namespace

    if remaining_arguments:
        raise ValueError("Unkown arguments: {}".format(", ".join(remaining_arguments)))

    return (parsed_namespaces, remaining_arguments)

def parse_known_arguments(subparser, unparsed_arguments):
    namespace = argparse.Namespace()
    remaining_arguments = []

    for argument in unparsed_arguments:
        if argument in subparser.parsed:
            value = unparsed_arguments[argument]
            setattr(namespace, argument, value)
        else:
            remaining_arguments.append(unparsed_arguments[argument])

    return (namespace, remaining_arguments)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = []

    for key in subparsers:
        subparser = subparsers[key]
        try:
            namespace, unparsed_args = subparser.parse_known_args(unparsed_arguments)
            parsed_args[key] = namespace
            unparsed_arguments = unparsed_args
        except SystemExit:
            pass

    remaining_args = unparsed_arguments

    return parsed_args, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
