def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    try:
        if filename:
            local_path = tmp_path / Path(filename).stem
            with ZipFile(archive_path) as zip:
                zip.extractall(local_path)
        else:
            local_path = tmp_path / archive_path.rpartition("/")[-1]
            subprocess.run(["tar", "-xf", archive_path, "-C", local_path])
        return local_path.resolve().as_uri()
    except Exception as e:
        raise ValueError(f"Error preparing repository from archive: {e}")

