import datetime

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency == "always":
        return None
    else:
        num, unit = frequency.split()
        if unit == "minutes":
            return datetime.timedelta(minutes=int(num))
        elif unit == "hours":
            return datetime.timedelta(hours=int(num))
        elif unit == "days":
            return datetime.timedelta(days=int(num))
        elif unit == "weeks":
            return datetime.timedelta(weeks=int(num))
        elif unit == "months":
            return datetime.timedelta(weeks=int(num))
        else:
            raise ValueError(f"Invalid frequency {frequency}")

def parse_frequency(frequency):
    if not frequency:
        return None
    frequency = frequency.lower()
    if frequency == "always":
        return None
    for unit, factor in [
        ("seconds", 1),
        ("minutes", 60),
        ("hours", 3600),
        ("days", 86400),
        ("weeks", 604800),
        ("months", 2629746),
        ("years", 31556952)
    ]:
        match = re.match("^[0-9](?:[0-9]*)(?:[.][0-9]+)? ?(seconds?|minutes?|hours?|days?|weeks?|months?|years?)$", frequency, re.IGNORECASE)
        if match:
            return datetime.timedelta(seconds=factor * float(match.group(1)))
    raise ValueError(f"Invalid frequency {frequency} is not in the format <number>+ {unit}")

