        return self.get_scale()  
    else:  
        self._validate_scale(other)  
        self.set_scale(other)  
        return self.get_scale()

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_.value

    if get_coordinate == "left":
        get_coordinate = lambda bin_: bin_.left
    elif get_coordinate == "right":
        get_coordinate = lambda bin_: bin_.right
    else:
        get_coordinate = lambda bin_: bin_.lower + (bin_.upper - bin_.lower) / 2

    points = [(get_coordinate(bin_), *make_value(bin_)) for bin_ in hist]

    if scale is None:
        scale = hist.scale
    elif scale == True:
        scale = hist.scale

    return graph(points, field_names=field_names, scale=scale)

