    """Convert a :class:`.histogram` to a :class:`.graph`.

    See docstring for parameter descriptions.
    """
    if make_value is None:
        make_value = lambda val: val

    if scale is None:
        scale = HistScale(hist[0].x, hist[-1].x)

    if not get_coordinate in ("left", "middle", "right"):
        raise ValueError(f"Invalid get_coordinate value: {get_coordinate}")

    graph = Graph(scale=scale)
    for bin in hist:
        x = getattr(bin, get_coordinate)
        value = make_value(bin)
        graph.add_point(Point(x, value))

    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not isinstance(hist, Histogram):
        raise TypeError("hist must be a Histogram but got {}".format(type(hist)))
    if not isinstance(make_value, Callable) and make_value is not None:
        raise TypeError("make_value must be callable but got {}".format(type(make_value)))
    if not get_coordinate in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be one of 'left', 'right', 'middle' but got {}".format(get_coordinate))
    if not isinstance(field_names, Tuple):
        raise TypeError("field_names must be a tuple of strings but got {}".format(type(field_names)))
    if len(field_names) != hist.dimension:
        raise ValueError("field_names must have length equal to the dimension of the histogram but got {} for dimension {}".format(len(field_names), hist.dimension))

    values = [make_value(v) if make_value else v for v in hist.values]
    # create the graph...
    graph = Graph(scale=scale) if scale else Graph()
    for bin_, value in zip(hist.bins, values):
        coordinate = {
            "left": bin_.left,
            "right": bin_.right,
            "middle": (bin_.left + bin_.right) / 2
        }[get_coordinate]
        fields = {n: v for n, v in zip(field_names, value)}
        fields["x"] = coordinate
        graph.add_point(**fields)
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative:
        if not iface.providedBy(candidate):
            raise Invalid("Candidate does not claim to provide interface.")
    for name in iface.names():
        method = getattr(candidate, name, None)
        if method is None:
            raise Invalid(f"No such method {name} in candidate.")
        spec = iface.get(name)
        if spec is None:
            raise Invalid(f"No such method {name} in interface.")
        try:
            spec(method)
        except Invalid:
            raise Invalid(f"Method {name} has invalid signature.")
    for name in iface.names(attributes=True):
        attribute = getattr(candidate, name, None)
        if attribute is None:
            raise Invalid(f"No such attribute {name} in candidate.")
        spec = iface.get(name, True)
        if spec is None:
            raise Invalid(f"No such attribute {name} in interface.")
        try:
            spec(attribute)
        except Invalid:
            raise Invalid(f"Attribute {name} has invalid type.")
    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    "Verify that *candidate* might correctly provide *iface*"
    if not tentative:
        assert iface.providedBy(candidate), \
            "{} does not provide {}".format(candidate, iface)

    for required in iface.names(required=True):
        if not hasattr(candidate, required):
            raise zope.interface.Invalid(
                "{} does not define required attribute {}".format(
                    candidate, required
                )
            )

    for provided in iface.names(required=False):
        if not hasattr(candidate, provided):
            raise zope.interface.Invalid(
                "{} does not define optional attribute {}".format(
