           not inspect.ismethod(getattr(candidate, method)):
            raise zope.interface.Invalid(
                "{} does not define required method {}".format(
                    candidate, method
                )
            )

    for attribute in iface.names(implemented=False):
        if not hasattr(candidate, attribute) or \
           not inspect.ismethod(getattr(candidate, attribute)):
            raise zope.interface.Invalid(
                "{} does not define optional attribute {}".format(
                    candidate, attribute
                )
            )

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    if not (tentative or iface.providedBy(candidate)):
        raise zope.interface.Invalid("Candidate does not claim to implement the interface.")

    missing = set(iface).difference(dir(candidate))
    if missing:
        raise zope.interface.Invalid("Candidate does not define (some) methods/attributes of the interface: " + ",".join(missing))

    for name in iface:
        if callable(iface[name]):
            # check method signature
            if not len(iface[name]) == len(candidate[name]):
                raise zope.interface.Invalid("Method " + name + " does not have the right number of arguments.")
            for i, spec in enumerate(iface[name]):
                try:
                    spec.validate(candidate[name][i])
                except ValueError as e:
                    raise zope.interface.Invalid("Method " + name + " argument " + str(i) + " has invalid type specifier.")
        else:
            # check attribute type
            if not isinstance(iface[name], type):
                raise zope.interface.Invalid("Attribute " + name + " does not have a valid type specifier.")
            if not isinstance(candidate[name], iface[name]):
                raise zope.interface.Invalid("Attribute " + name + " does not have the correct type.")

    return True

def verifyObject(iface, candidate, tentative=False):
    # Making sure the candidate claims that it provides the interface
    if not tentative:
        assert isinstance(iface, Interface)
        assert iface.providedBy(candidate)
        assert iface.implementedBy(candidate.__class__)

    # Making sure the candidate defines all the necessary methods
    for name, func in iface.getMethods():
        try:
            candidate__getattr__(name)
        except AttributeError:
            raise Invalid("Method '{0}' is not provided by {1}.".format(name, candidate))

    # Making sure the methods have the correct signature
    for name, func in iface.getMethods():
        try:
            candidate_func = candidate.__getattr__(name)
            assert len(func.signature) == len(candidate_func.signature)
            for i, param in enumerate(func.signature):
                assert param[0] == candidate_func.signature[i][0]
                assert param[1] == candidate_func.signature[i][1]
        except Invalid:
            raise Invalid("Method '{0}' has an incorrect signature for {1}.".format(name, candidate))

    # Making sure the candidate defines all the necessary attributes
    for name, typ in iface.getAttributes():
        try:
            candidate_attr = candidate.__getattr__(name)
            assert typ(candidate_attr)
        except AttributeError:
            raise Invalid("Attribute '{0}' is not provided by {1}.".format(name, candidate))

    return True

