            raise zope.interface.Invalid("Candidate does not define the necessary attribute '{0}'".format(name))
        else:
            if not zope.interface.match(spec, attr):
                raise zope.interface.Invalid("Candidate attribute '{0}' does not have the correct type or an appropriate default value".format(name))
    return True

