def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Check for explicit metaclass
    if explicit_mc is not None:
        return explicit_mc

    # Check if there are multiple bases and inheritance is not explicit (no __metaclass__)
    if len(bases) > 1 and not any(hasattr(base, '__metaclass__') for base in bases):
        # Raise a warning if a subclass is being created
        if issubclass(cls, bases):
            warn(RuntimeWarning("Different variables have no effect when creating a subclass"))
        # Use type metaclass as the default
        return type

    # Return the first base's metaclass
    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    # No metaclass could be found
    raise TypeError("Could not determine metaclass")

def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        # use explicit metaclass
        return type(explicit_mc)
    elif len(bases) > 1:
        # multiple bases, use the one that's a class
        for base in bases:
            if isinstance(base, type):
                return type(base)
        raise TypeError("Couldn't determine metaclass from bases: " + str(bases))
    else:
        # single base, return the type of the base
        return type(bases[0])

