def find_tags(text, replacer=None):
        """Find tags in text.

        Tries to ignore tags inside code blocks.

        Optionally, if passed a "replacer", will also replace the tag word with the result
        of the replacer function called with the tag word.

        Returns a set of tags and the original or replaced text.
        """

        text_upper = text.upper()
        code_blocks = []
        idx = 0
        for i, block in enumerate(text_upper.split("{code}")):
            if i % 2 == 0:
                continue
            code_blocks.append(block.split("{/code}")[0])
            idx += 1

        tags = set()
        for i, block in enumerate(text_upper.split("`")):
            if i % 2 == 0:
                continue
            for keyword in block.split(" "):
                if keyword not in code_blocks[idx]:
                    tags.add(keyword)
            idx += 1

        if replacer is not None:
            text = text.replace("`", f"`{replacer}`")

        return tags, text

