    for word in text.split():
        if word.startswith("<!--") and word.endswith("-->"):
            in_code_block = not in_code_block
        elif not in_code_block:
            if replacer and word.startswith("#"):
                new_word = replacer(word)
                new_text = new_text.replace(word, new_word)
                tags.add(new_word)
            elif word.startswith("#"):
                tags.add(word)

    return tags, new_text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Get all URLs in the text
    urls = re.findall(r"(?i)http(s)?://[^\s]+", text)
    # Create a dictionary to store the processed text and links
    processed_text = {}
    for url in urls:
        # Add a new attribute "link" to the URL
        processed_text[url] = {"link": f"<a href=\"{url}\">{url}</a>"}
    # Replace all URLs in the text with the processed link
    for url in processed_text:
        text = text.replace(url, processed_text[url]["link"])
    # Return the processed text
    return text

