    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    Arguments:
        url (str): The full base url with protocol, ie 'https://example.com'
        document_path (str): Custom NodeInfo document path if supplied (optional)

    Returns:
        dict: The generated NodeInfo .well-known document.
    """
    # validate the input
    if not url.startswith('https://'):
        raise ValueError(f"Invalid URL: {url}. Must start with 'https://'")

    # retrieve the document metadata
    if document_path:
        metadata = retrieve_document_metadata(document_path)
    else:
        metadata = retrieve_document_metadata(url)

    # construct the .well-known document
    nodeinfo = {
        'version': '1.0',
        'software': {
            'name': 'PyDiaspora',
            'version': '0.1.0',
            'url': 'https://github.com/lechtc/pydiaspora',
        },
        'protocols': ['activitypub'],
        'services': {
            'inbound': [],
            'outbound': [],
        },
        'openRegistrations': True,
    }

    # add the required properties
    nodeinfo['urls'] = {
        'nodeinfo': url + document_path,
    }

    # add the metadata properties
    nodeinfo['metadata'] = metadata

    # return the generated NodeInfo document
    return nodeinfo

